# exact tiling target 7 cells with objects; construct pieces in source orientation
mask={(r,c) for r in range(15) for c in range(7) if a[r,c]==7}
pieces={
 '1': {(dr,dc) for dr in range(2) for dc in range(5)},
 '6': {(dr,dc) for dr in range(6) for dc in range(2)},
 '2': {(dr,dc) for dr in range(2) for dc in range(2)},
 '8a': {(0,dc) for dc in range(4)},
 '8b': {(0,dc) for dc in range(4)},
 '3': {(dr,dc) for dr in range(3) for dc in range(2)},
 '0': {(0,0)}
}
# all translations only
placements={}
for name,shape in pieces.items():
 h=max(x for x,y in shape)+1; w=max(y for x,y in shape)+1
 arr=[]
 for r in range(15-h+1):
  for c in range(7-w+1):
   cells={(r+x,c+y) for x,y in shape}
   if cells<=mask: arr.append((r,c,cells))
 placements[name]=arr
{n:len(p) for n,p in placements.items()}

sol=sols[0]
out=np.array(a[:,:7],copy=True)
colors={'1':1,'6':6,'2':2,'8a':8,'8b':8,'3':3,'0':0}
for n,(r,c) in sol.items():
 for dr,dc in pieces[n]:
  assert out[r+dr,c+dc]==7
  out[r+dr,c+dc]=colors[n]
print('\n'.join(' '.join(map(str,row)) for row in out)); print(Counter(out.flat))
